#!/usr/bin/env python3
"""Independent verifier: recompute every demand from the submitted files + corpus and test hard limits."""
import csv, json, math, os, sys, re
from collections import defaultdict

ROOT = '/filesystem/field_eng__constructability_4d__blind'
OUT = os.environ.get('CHECK_OUT', os.path.join(ROOT, 'output'))
FAIL = []

def rd(p):
    with open(os.path.join(ROOT, p)) as f:
        return list(csv.DictReader(f))

def rdout(p):
    with open(os.path.join(OUT, p)) as f:
        return list(csv.DictReader(f))

def bad(msg):
    FAIL.append(msg)

# ---- corpus ---------------------------------------------------------------
storey = {r['level_id']: r for r in rd('model/storey_schedule.csv')}
zone = {r['zone_id']: r for r in rd('model/zone_schedule.csv')}
slab = {r['slab_id'][2:]: r for r in rd('model/slab_schedule.csv')}
zws = {r['zone_lift']: r for r in rd('programme/zone_work_schedule.csv')}
acts = {r['activity_id']: r for r in rd('programme/activity_list.csv')}
occ = {r['zone_lift'] for r in rd('site/existing_occupation.csv')}
mix = {r['mix_id']: r for r in rd('catalogue/concrete_mix_schedule.csv')}
scaf = {r['system']: r for r in rd('catalogue/scaffold_catalogue.csv')}
comp = {r['component']: r for r in rd('catalogue/scaffold_components.csv')}
duty = {r['duty_class']: r for r in rd('catalogue/scaffold_duty_classes.csv')}
shore = {r['post_type']: r for r in rd('catalogue/shoring_catalogue.csv')}
gridopt = [float(r['spacing_ft']) for r in rd('catalogue/shoring_grid_options.csv')]
chart = [(float(r['radius_ft']), float(r['rated_capacity_lb'])) for r in rd('site/crane_chart.csv')]
pos = {r['position_id']: r for r in rd('site/crane_standing_positions.csv')}
tba = rd('site/power_line_clearance_table_A.csv')

def cap_at(r):
    if r <= chart[0][0]:
        return chart[0][1]
    for (r0, c0), (r1, c1) in zip(chart, chart[1:]):
        if r0 <= r <= r1:
            return c0 + (c1 - c0) * (r - r0) / (r1 - r0)
    return 0.0

# ---- expected zone-lift design -------------------------------------------
EXP = {}
for zl, r in zws.items():
    z = zone[r['zone']]
    band = z['band']
    bucket = band in ('E', 'F', 'G')
    occupied = zl in occ
    sw = float(slab[zl]['self_weight_psf'])
    q = sw + 10.0 + (75.0 if bucket else 50.0) + (15.0 if occupied else 0.0)
    dclass = 'heavy' if bucket else ('medium' if occupied else 'light')
    req_ext = float(storey[r['level']]['soffit_ft']) - float(storey[r['level']]['lift_base_ft']) - 0.75
    EXP[zl] = dict(zone=r['zone'], level=r['level'], area=float(r['area_sf']), face=float(r['face_length_ft']),
                   h=float(r['scaffold_height_ft']), clear=float(r['clear_height_ft']), q=q,
                   dclass=dclass, mil=float(duty[dclass]['maximum_intended_load_lb_per_bay']),
                   strike=int(mix[r['mix_id']]['strike_days']), core=z['stair_core'] == 'yes',
                   laydown=int(r['laydown_units']), wind=float(r['wind_exposed_sf']),
                   heaviest=float(r['heaviest_pick_lb']), req_ext=req_ext,
                   cx=(float(z['x0_ft']) + float(z['x1_ft'])) / 2,
                   cy=(float(z['y0_ft']) + float(z['y1_ft'])) / 2)

# ---- construction sequence ------------------------------------------------
seq = rdout('construction_sequence.csv')
byid = {r['activity_id']: r for r in seq}
if len(seq) != len(acts):
    bad('sequence rows %d != issued activities %d' % (len(seq), len(acts)))
for a in acts.values():
    r = byid.get(a['activity_id'])
    if r is None:
        bad('missing activity %s' % a['activity_id'])
        continue
    if int(r['duration_days']) != int(a['duration_days']):
        bad('%s duration %s != issued %s' % (a['activity_id'], r['duration_days'], a['duration_days']))
    if int(r['finish_day']) != int(r['start_day']) + int(r['duration_days']):
        bad('%s finish != start+dur' % a['activity_id'])
    if int(r['start_day']) < 0:
        bad('%s negative start' % a['activity_id'])
    if abs(float(r['crane_hours']) - float(a['crane_hours'])) > 1e-9:
        bad('%s crane hours differ from issued' % a['activity_id'])
    if r['zone'] != a['zone'] or r['level'] != a['level'] or r['activity_type'] != a['activity_type']:
        bad('%s zone/level/type mismatch' % a['activity_id'])

# precedence (issued only)
for a in acts.values():
    r = byid.get(a['activity_id'])
    if not r:
        continue
    for p in filter(None, (a['predecessors'] or '').split(';')):
        pr = byid.get(p)
        if pr and int(pr['finish_day']) > int(r['start_day']):
            bad('precedence %s -> %s violated' % (p, a['activity_id']))

# internal chain per zone lift + level sequencing + strike age
for zl, e in EXP.items():
    got = {}
    for a in acts.values():
        if a['zone_lift'] == zl:
            got[a['activity_type']] = byid.get(a['activity_id'])
    if len(got) != 7:
        bad('%s has %d activities' % (zl, len(got)))
        continue
    s = {k: int(v['start_day']) for k, v in got.items()}
