    if dr < float(cr['radius_ft']) - 1e-9: bad('%s demarcated radius < working radius' % zl)
    if dr > float(p['distance_to_power_line_ft']) - 10.0 + 1e-9: bad('%s demarcated radius > 145' % zl)

# ---- workspace volume ------------------------------------------------------
for a in acts.values():
    r = byid.get(a['activity_id'])
    if not r: continue
    e = EXP[a['zone_lift']]
    t = twz[a['zone_lift']]
    if a['activity_type'] in ('SCAF', 'SCST'):
        vol = e['face'] * float(t['scaffold']['base_width_ft']) * e['h']
    else:
        vol = e['area'] * e['clear']
    if abs(float(r['workspace_volume_cf']) - vol) > 0.05 * vol:
        bad('%s workspace %.1f vs %.1f' % (a['activity_id'], float(r['workspace_volume_cf']), vol))

# ---- register --------------------------------------------------------------
reg = rdout('constraint_register.csv')
print('register rows', len(reg))
for r in reg:
    if not r.get('requirement') or not r.get('document') or not r.get('clause'):
        bad('register row incomplete: %s' % r)

# ---- method note -----------------------------------------------------------
note = open(os.path.join(OUT, 'method_note.md')).read()
wc = len(re.findall(r'\S+', note))
print('method note words', wc)
if wc < 200: bad('method note < 200 words')
for kw in ('LivingBIM', 'CC BY 4.0', '17934615'):
    if kw not in note: bad('method note missing %s' % kw)

print('worst utilisations:', {k: round(v, 3) for k, v in worst.items()})
print('FAILURES:', len(FAIL))
for f in FAIL[:40]:
    print('  -', f)
sys.exit(1 if FAIL else 0)

