import csv
ROOT='/filesystem/field_eng__constructability_4d__blind'
iss={r['activity_id']:r for r in csv.DictReader(open(ROOT+'/programme/activity_list.csv'))}
seq={r['activity_id']:r for r in csv.DictReader(open('construction_sequence.csv'))}
print('issued',len(iss),'sequence',len(seq),'id sets equal',set(iss)==set(seq))
bad=[]
for k,a in iss.items():
    r=seq[k]
    if int(r['duration_days'])!=int(a['duration_days']): bad.append((k,'dur'))
    if abs(float(r['crane_hours'])-float(a['crane_hours']))>1e-9: bad.append((k,'crane'))
    if int(r['finish_day'])!=int(r['start_day'])+int(r['duration_days']): bad.append((k,'finish'))
print('bad',bad[:5],len(bad))
print('max finish',max(int(r['finish_day']) for r in seq.values()))
EOF
